SELECT n.id, n.user_id, n.author_id, n.course_id, n.chapter_id, n.section_id, n.note_moment, n.content, n.is_private, n.hidden, n.hidden_reason, n.gathered_note_id, n.is_gathered, n.liked_times, n.create_time, n.update_time, EXISTS(SELECT 1 FROM note g WHERE g.gathered_note_id = n.id AND g.user_id = #{userId}) AS gathered_by_me FROM note n WHERE n.hidden = 0 AND n.is_gathered = 0
AND n.section_id = #{sectionId}
AND n.course_id = #{courseId}
AND (n.is_private = 0 OR n.user_id = #{userId}) ORDER BY n.note_moment

SELECT DISTINCT user_id
FROM note
WHERE gathered_note_id = #{noteId}
